import java.util.*;

public class Solution {
    public static int equalStacks(int[] h1, int[] h2, int[] h3) {
        Deque<Integer> s1 = build(h1);
        Deque<Integer> s2 = build(h2);
        Deque<Integer> s3 = build(h3);
        while (true) {
            int t1 = sum(s1), t2 = sum(s2), t3 = sum(s3);
            if (t1 == t2 && t2 == t3) return t1;
            int max = Math.max(t1, Math.max(t2, t3));
            if (t1 == max && !s1.isEmpty()) s1.pop();
            else if (t2 == max && !s2.isEmpty()) s2.pop();
            else if (!s3.isEmpty()) s3.pop();
            else return 0;
        }
    }

    private static Deque<Integer> build(int[] arr) {
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = arr.length - 1; i >= 0; i--) st.push(arr[i]);
        return st;
    }

    private static int sum(Deque<Integer> st) {
        int total = 0;
        for (int v : st) total += v;
        return total;
    }

    public static void main(String[] args) {
        System.out.println(equalStacks(
            new int[]{3, 2, 1, 1, 1},
            new int[]{4, 3, 2},
            new int[]{1, 1, 4, 1}));
    }
}

