        if t1 == t2 == t3:
            return t1
        biggest = max(t1, t2, t3)
        if t1 == biggest and s1:
            s1.pop(0)
        elif t2 == biggest and s2:
            s2.pop(0)
        elif s3:
            s3.pop(0)
        else:
            return 0


if __name__ == "__main__":
