public class Solution {
    public static int equalStacks(int[] h1, int[] h2, int[] h3) {
        long t1 = total(h1), t2 = total(h2), t3 = total(h3);
        int i = 0, j = 0, k = 0;
        while (true) {
            if (t1 == t2 && t2 == t3) return (int) t1;
            if (t1 >= t2 && t1 >= t3) {
                if (i == h1.length) return 0;
                t1 -= h1[i++];
            } else if (t2 >= t1 && t2 >= t3) {
                if (j == h2.length) return 0;
                t2 -= h2[j++];
            } else {
                if (k == h3.length) return 0;
                t3 -= h3[k++];
            }
        }
    }

    private static long total(int[] arr) {
        long s = 0;
        for (int v : arr) s += v;
        return s;
    }

    public static void main(String[] args) {
        System.out.println(equalStacks(
            new int[]{3, 2, 1, 1, 1},
            new int[]{4, 3, 2},
            new int[]{1, 1, 4, 1}));
    }
}

